<?php $labels=['vehicles'=>'Vehículos','drivers'=>'Repartidores','delivery_runs'=>'Rutas manuales'];$resourceId=$resourceId??0;$showResourceForm=$showResourceForm??false; ?>
<div class="deliveries-editor deliveries-resources"><section class="admin-page-head"><div><p class="admin-kicker">LOGÍSTICA</p><h1><?= e($labels[$kind]) ?></h1><p>Organiza los recursos de cada sucursal y la secuencia de las rutas de reparto.</p></div><div class="admin-head-actions"><a class="admin-secondary-button" data-admin-modal-cancel href="/admin/deliveries">Volver a entregas</a><?php if(!$showResourceForm&&!$resourceId):?><a class="admin-primary-button" data-admin-form-link href="/admin/deliveries/resources?kind=<?= e($kind) ?>&amp;new=1">+ Registrar <?= $kind==='vehicles'?'vehículo':($kind==='drivers'?'repartidor':'ruta') ?></a><?php endif?></div></section>
<nav class="admin-catalog-nav" aria-label="Recursos de entrega"><?php foreach($labels as $k=>$label):?><a data-admin-form-link href="/admin/deliveries/resources?kind=<?= e($k) ?>" class="<?= $kind===$k?'is-active':'' ?>"><?= e($label) ?></a><?php endforeach?></nav>
<?php if(!$showResourceForm&&!$resourceId):?><section class="admin-panel admin-table-panel deliveries-directory"><header class="deliveries-directory-heading"><div><h2><?= e($labels[$kind]) ?> registrados</h2><p><?= $kind==='delivery_runs'?'Las rutas conservan la fecha, el vehículo y el repartidor de su creación.':'Consulta el estado y la disponibilidad de cada recurso.' ?></p></div></header><?php if(!$page->items):?><div class="deliveries-empty"><h3>Aún no hay <?= e(strtolower($labels[$kind])) ?> registrados</h3><p>Registra los recursos confirmados de tu sucursal para organizar las entregas.</p></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Recurso</th><th>Sucursal</th><?php if($kind==='delivery_runs'):?><th>Fecha</th><th>Vehículo / repartidor</th><?php else:?><th>Estado</th><th>Disponibilidad</th><th>Acciones</th><?php endif?></tr></thead><tbody><?php foreach($page->items as $r):?><tr data-resource-id="<?= e($r['id']) ?>"><td data-label="Recurso"><div><strong><?= e($r['name']) ?></strong><small><?= e('#'.$r['id'].($kind==='delivery_runs'?'':' · '.$r['code'])) ?></small></div></td><td data-label="Sucursal"><?= e($r['branch_name']) ?></td><?php if($kind==='delivery_runs'):?><td data-label="Fecha"><?= e($r['scheduled_date']) ?></td><td data-label="Vehículo / repartidor"><?= e('#'.$r['vehicle_id'].' / #'.$r['driver_id']) ?></td><?php else:?><td data-label="Estado"><span class="deliveries-status"><?= (int)$r['is_active']===1?'Activo':'Inactivo' ?></span></td><td data-label="Disponibilidad"><?= (int)$r['is_available']===1?'Disponible':'No disponible' ?></td><td class="admin-actions"><a class="admin-secondary-button" data-admin-form-link href="/admin/deliveries/resources?<?= e(http_build_query(['kind'=>$kind,'resource_id'=>$r['id'],'offset'=>$page->offset])) ?>">Editar</a></td><?php endif?></tr><?php endforeach?></tbody></table></div><?php endif?></section>
<?php if($page->offset||$page->hasMore):?><nav class="admin-pagination" aria-label="Páginas de recursos"><?php if($page->offset):?><a data-admin-form-link href="/admin/deliveries/resources?<?= e(http_build_query(['kind'=>$kind,'offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a data-admin-form-link href="/admin/deliveries/resources?<?= e(http_build_query(['kind'=>$kind,'offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav><?php endif?>
<?php else:?>
<?php $forms=$showResourceForm?[null]:array_values(array_filter($page->items,fn($r)=>(int)$r['id']===$resourceId));if(!$forms):?><p class="admin-alert" role="status">El recurso no está en esta página. Vuelve al listado para seleccionarlo.</p><?php endif?>
<?php foreach($forms as $resource):?><?php if($kind==='delivery_runs'&&$resource)continue;?>
<section class="admin-panel"><div class="deliveries-section-heading"><h2><?= $resource?'Editar recurso':'Registrar recurso' ?></h2><p><?= $kind==='delivery_runs'?'Selecciona un vehículo y un repartidor activos y disponibles de la sucursal elegida.':'Captura los datos internos y confirma si el recurso está disponible para entregas.' ?></p></div>
<form method="post" action="/admin/deliveries/resources" class="admin-form" data-delivery-resource><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="kind" value="<?= e($kind) ?>"><input type="hidden" name="operation_key" value="<?= e(bin2hex(random_bytes(20))) ?>"><input type="hidden" name="id" value="<?= e($resource['id']??'') ?>"><input type="hidden" name="lock_version" value="<?= e($resource['lock_version']??'0') ?>">
<div class="admin-form-grid"><label class="admin-field"><span>Sucursal</span><select name="branch_id" required><?php foreach($branches as $b):?><option value="<?= e($b['id']) ?>" <?= ($resource['branch_id']??'')==$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Nombre / ficha básica</span><input name="name" maxlength="120" value="<?= e($resource['name']??'') ?>" required></label>
<?php if($kind==='delivery_runs'):?><label class="admin-field deliveries-field-full"><span>Fecha de ruta</span><input type="date" name="scheduled_date" required></label><?php foreach(['vehicle_id'=>['Vehículo',$vehicleOptions??[]],'driver_id'=>['Repartidor',$driverOptions??[]]] as $field=>[$label,$options]):?><label class="admin-field"><span><?= e($label) ?></span><select name="<?= e($field) ?>" required data-delivery-resource-select><option value="">Selecciona <?= $field==='vehicle_id'?'un vehículo':'un repartidor' ?></option><?php foreach($options as $option):?><option value="<?= e($option['id']) ?>" data-branch-id="<?= e($option['branch_id']) ?>"><?= e($option['name'].' · '.$option['code']) ?></option><?php endforeach?></select></label><?php endforeach?><?php else:?><label class="admin-field deliveries-field-full"><span>Código estable</span><input name="code" value="<?= e($resource['code']??'') ?>" maxlength="40" required></label><?php foreach(['is_active'=>'Estado activo','is_available'=>'Disponible']as $flag=>$label):?><label class="admin-field"><span><?= e($label) ?></span><select name="<?= e($flag) ?>"><option value="1" <?= ($resource[$flag]??1)==1?'selected':'' ?>>Sí</option><option value="0" <?= ($resource[$flag]??1)==0?'selected':'' ?>>No</option></select></label><?php endforeach;endif?></div><?php if($kind==='delivery_runs'):?><p class="deliveries-section-copy" role="status" data-delivery-resource-status>Los recursos se filtran por sucursal. Si falta alguno, regístralo o revisa su disponibilidad.</p><?php endif?><div class="admin-head-actions"><a class="admin-secondary-button" data-admin-form-link href="/admin/deliveries/resources?kind=<?= e($kind) ?>">Cancelar</a><button class="admin-primary-button">Guardar recurso</button></div></form></section><?php endforeach?>
<a class="deliveries-text-link" data-admin-form-link href="/admin/deliveries/resources?kind=<?= e($kind) ?>">Volver al listado</a>
<?php endif?></div>
